import numpy as np

def precision_at_k(relevance: list[int], k: int) -> float:
    return sum(relevance[:k]) / k

def recall_at_k(relevance: list[int], num_relevant: int, k: int) -> float:
    return sum(relevance[:k]) / num_relevant

def average_precision(relevance: list[int]) -> float:
    hits, sum_prec = 0, 0.0
    for i, rel in enumerate(relevance, 1):
        if rel:
            hits += 1
            sum_prec += hits / i
    return sum_prec / max(1, sum(relevance))

def mrr(relevances: list[list[int]]) -> float:
    rr_sum = 0.0
    for rel in relevances:
        for i, r in enumerate(rel, 1):
            if r:
                rr_sum += 1 / i
                break
    return rr_sum / len(relevances)

def ndcg_at_k(relevance: list[int], k: int) -> float:
    def dcg(rels, k):
        return sum(r / np.log2(i + 2) for i, r in enumerate(rels[:k]))
    actual_dcg = dcg(relevance, k)
    ideal_dcg  = dcg(sorted(relevance, reverse=True), k)
    return actual_dcg / ideal_dcg if ideal_dcg > 0 else 0.0

# Example
rel = [1, 0, 1, 0, 0, 1, 0, 0, 0, 1]  # 1=relevant, 0=not
print(f"P@5:    {precision_at_k(rel, 5):.3f}")   # 0.400
print(f"R@5:    {recall_at_k(rel, 4, 5):.3f}")    # 0.500
print(f"AP:     {average_precision(rel):.3f}")     # 0.598
print(f"NDCG@5: {ndcg_at_k(rel, 5):.3f}")        # 0.669
